import assert from "node:assert/strict";
import { test } from "node:test";
import { decide } from "../screens/access.ts";
import { schema } from "../app/books/page.schema.ts";

test("books-list is refused to someone signed in without books.read", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: [] }), "refused");
});

test("books-list sends someone signed out to sign in", () => {
  assert.equal(decide(schema.permission, { signedIn: false, permissions: [] }), "sign-in");
});

test("books-list opens to someone who holds books.read", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: ["books.read"] }), "allowed");
});
